 "content": "from collections import Counter, deque


def _shape(coords):
    if not coords:
        return frozenset()
    r0 = min(r for r, c in coords)
    c0 = min(c for r, c in coords)
    return frozenset((r - r0, c - c0) for r, c in coords)


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The repeated frame color is the non-background color forming the left panels.
    counts = Counter(v for row in grid for v in row if v != 0)
    frame = counts.most_common(1)[0][0]
    left_width = 0
    for row in grid:
        run = 0
        while run < w and row[run] == frame:
            run += 1
        left_width = max(left_width, run)
    # Full frame rows separate adjacent panels; the panels share separator rows.
    separators = [r for r in range(h) if all(grid[r][c] == frame for c in range(left_width))]
    if len(separators) < 2:
        return [row[:left_width] for row in grid]

    # Collect the shapes and colors of the colored objects on the right.
    seen = set()
    objects = {}
    for r in range(h):
        for c in range(left_width, w):
            color = grid[r][c]
            if color == 0 or color == frame or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and left_width <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            objects[_shape(cells)] = color

    out = [row[:left_width] for row in grid]
    for top, bottom in zip(separators, separators[1:]):
        holes = [(r, c) for r in range(top + 1, bottom)
                 for c in range(1, left_width - 1) if grid[r][c] == 0]
        color = objects.get(_shape(holes))
        if color is not None:
            for r, c in holes:
                out[r][c] = color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
